def uid(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')[:40]
def section(name, widgets, bg='#ffffff'):
    return {'id':'s-'+uid(name),'name':name,'style':{'backgroundType':'color','backgroundColor':bg,'paddingY':22,'gap':12,'maxWidthType':'full','innerMaxWidth':536},'columns':[{'id':'c-'+uid(name),'name':'Content','spans':{'base':12,'md':12,'lg':12},'widgets':widgets}]}
def rich(text, align='left'):
    return {'id':'w-'+hashlib.sha1(text.encode()).hexdigest()[:10],'type':'rich_text','name':'Text','props':{'html':text,'align':align}}
def heading(text, level=2):
    return {'id':'h-'+hashlib.sha1((str(level)+text).encode()).hexdigest()[:10],'type':'heading','name':'Heading','props':{'text':text,'level':level,'align':'left','color':'#162849','fontSize':22 if level==1 else 18}}
def image_block(url, alt, name='Campaign image'):
    return {'id':'i-'+hashlib.sha1((url+alt).encode()).hexdigest()[:10],'type':'image','name':name,'props':{'url':url,'alt':alt,'align':'center','width':'100%','borderRadius':'8px'}}
def build(d):
    slug,category,subject,pre,eyebrow,title,intro,prompt,reply,cta,url,color,image,cards=d
    title_e=escape(title); pre_e=escape(pre); image_url=ASSET_BASE+image
    sections=[]
    sections.append(section('GoRealo brand',[rich(f'<p style="margin:0"><a href="{BASE}/"><img src="{LOGO}" alt="GoRealo" width="154" style="display:block;width:154px;max-width:100%;height:auto;border:0"></a></p><p style="margin:10px 0 0;color:#667085;font-size:11px;letter-spacing:1.5px">MORTGAGE OPTIONS, MADE CLEAR</p>')]))
    sections.append(section('Campaign introduction',[rich(f'<p style="margin:0 0 12px;color:{color};font-size:11px;font-weight:bold;letter-spacing:2px">{escape(eyebrow)}</p>'),heading(title,1),rich(f'<p style="font-size:16px;line-height:1.7;color:#374151">{escape(intro)}</p><p style="font-size:16px;line-height:1.7;color:#162849;font-weight:bold">{escape(prompt)}</p>'),image_block(image_url,'GoRealo: '+category)],'#f0f5ff'))
    # Each email has its own editorial cadence, story, CTA, and closing prompt.
    for h,body in cards:
        sections.append(section(h,[heading(h),rich(f'<p style="font-size:15px;line-height:1.75;color:#4b5563">{escape(body)}</p>')]))
    sections.append(section('Personal reply',[rich(f'<p style="font-size:15px;line-height:1.75;color:#374151">{escape(reply)}</p><p style="font-size:15px;line-height:1.75;color:#374151">Warmly,<br><strong>The GoRealo Team</strong></p>')]))
    sections.append(section('Primary call to action',[{'id':'cta-'+uid(slug),'type':'button','name':'Primary CTA','props':{'text':cta,'url':url,'align':'left','backgroundColor':color,'textColor':'#ffffff','size':'md','paddingX':24,'paddingY':14,'borderRadius':'4px'}},rich('<p style="font-size:13px;color:#667085;line-height:1.6">Prefer to talk? Call <a href="tel:+18667139292" style="color:#003FDA">1-866-713-9292</a> or reply to this email.</p>')]))
    sections.append(section('Compliance footer',[rich(f'<p style="font-size:11px;line-height:1.7;color:#667085">{FOOTER}</p><p style="font-size:11px;line-height:1.7;color:#667085"><a href="https://www.gorealo.com/privacy-policy/" style="color:#003FDA">Privacy</a> · <a href="{{{{unsubscribe_url}}}}" style="color:#003FDA">Unsubscribe</a></p>')],'#f4f6f9'))
    builder={'builder':'mailpurse','version':1,'meta':{'name':'GoRealo — '+category},'style':{},'customCss':'','sections':sections}
    cards_html=''.join(f'<tr><td style="padding:14px 0;border-bottom:1px solid #e5eaf1"><h2 style="font-size:17px;line-height:1.35;margin:0 0 7px;color:#162849">{escape(h)}</h2><p style="font-size:15px;line-height:1.75;color:#4b5563;margin:0">{escape(body)}</p></td></tr>' for h,body in cards)
    html_doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(subject)}</title></head><body style="margin:0;background:#f1f4f8;font-family:Arial,Helvetica,sans-serif"><div style="display:none;max-height:0;overflow:hidden;mso-hide:all">{pre_e}</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#f1f4f8"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="600" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:600px;background:#fff"><tr><td style="padding:24px 30px;border-top:5px solid #0BFF56"><a href="{BASE}/"><img src="{LOGO}" width="154" alt="GoRealo" style="display:block;width:154px;max-width:100%;height:auto;border:0"></a><p style="margin:9px 0 0;color:#667085;font-size:11px;letter-spacing:1.5px">MORTGAGE OPTIONS, MADE CLEAR</p></td></tr><tr><td style="padding:30px;background:#f0f5ff"><p style="margin:0 0 12px;color:{color};font-size:11px;font-weight:bold;letter-spacing:2px">{escape(eyebrow)}</p><h1 style="font-size:30px;line-height:1.2;margin:0 0 16px;color:#162849">{title_e}</h1><p style="font-size:16px;line-height:1.7;color:#374151;margin:0 0 14px">{escape(intro)}</p><p style="font-size:16px;line-height:1.7;color:#162849;font-weight:bold;margin:0">{escape(prompt)}</p><p style="margin:20px 0 0"><img src="{image_url}" alt="GoRealo: {escape(category)}" width="540" style="display:block;width:100%;max-width:540px;height:auto;border:0;border-radius:8px"></p></td></tr><tr><td style="padding:22px 30px"><table role="presentation" width="100%" cellspacing="0" cellpadding="0">{cards_html}</table><p style="font-size:15px;line-height:1.75;color:#374151;margin:22px 0">{escape(reply)}</p><p style="font-size:15px;line-height:1.75;color:#374151">Warmly,<br><strong>The GoRealo Team</strong></p><table role="presentation" cellspacing="0" cellpadding="0" style="margin:22px 0"><tr><td bgcolor="{color}" style="border-radius:4px"><a href="{url}" style="display:inline-block;padding:14px 24px;color:#fff;text-decoration:none;font-size:15px;font-weight:bold">{escape(cta)}</a></td></tr></table><p style="font-size:13px;line-height:1.7;color:#667085">Prefer to talk? Call <a href="tel:+18667139292" style="color:#003FDA">1-866-713-9292</a> or reply to this email.</p></td></tr><tr><td style="padding:20px 30px;background:#f4f6f9"><p style="font-size:11px;line-height:1.7;color:#667085;margin:0">{FOOTER}</p><p style="font-size:11px;line-height:1.7;color:#667085"><a href="https://www.gorealo.com/privacy-policy/" style="color:#003FDA">Privacy</a> · <a href="{{{{unsubscribe_url}}}}" style="color:#003FDA">Unsubscribe</a></p></td></tr></table></td></tr></table></body></html>'''
    plain=re.sub(r'<[^>]+>',' ',html_doc)
    plain=' '.join(plain.split())
    record={'slug':'gorealo-'+slug,'name':'GoRealo — '+category,'description':f'Subject: {subject} | Preheader: {pre}','type':'email','builder':'mailpurse','html_content':html_doc,'plain_text_content':plain,'builder_data':builder,'thumbnail':f'{PREVIEW_BASE}/{slug}.png','is_active':True,'available_to_all_groups':True,'settings':{'source':'gorealo-campaign-pack','subject':subject,'preheader':pre,'category':category,'primary_cta':cta,'primary_url':url,'source_image':image}}
    target=ROOT/'templates'/slug; target.mkdir(parents=True,exist_ok=True)
    (target/'email.html').write_text(html_doc+'\n')
    (target/'template.json').write_text(json.dumps(record,indent=2,ensure_ascii=False)+'\n')
    (target/'builder.json').write_text(json.dumps(builder,indent=2,ensure_ascii=False)+'\n')
    return record

records=[build(d) for d in DATA]
(ROOT/'templates.json').write_text(json.dumps(records,indent=2,ensure_ascii=False)+'\n')
print(f'Built {len(records)} HTML emails with native MailerFox block data.')
